actions.script:
nameMap = {}
const byEntity = {}
for (const item of Array.from(recordList || [])) {
    if (!item || !item.recordEntityName || item.recordId == null) continue
    const entry = byEntity[item.recordEntityName] = byEntity[item.recordEntityName] || {idField: null, ids: new Set()}
    if (item.idField && !entry.idField) entry.idField = item.idField
    entry.ids.add(String(item.recordId))
}
const NAME_FIELDS = ['requestName', 'workEffortName', 'orderName', 'productName', 'categoryName', 'facilityName', 'assetName',
    'subject', 'description']
for (const entityName of Object.keys(byEntity)) {
    const ids = Array.from(byEntity[entityName].ids)
    const found = {}
    ec.message.pushErrors()
    try {
        if (entityName === 'mantle.party.Party') {
            for (const party of ec.entity.find('mantle.party.PartyDetail').condition('partyId', 'in', ids).list())
                found[party.partyId] = {title: (ec.resource.expand('PartyNameOnlyTemplate', '', party) || '').trim(), partyTypeEnumId: party.partyTypeEnumId ?? null}
        } else {
            const ed = ec.entity.getEntityDefinition(entityName)
            const pk = byEntity[entityName].idField || (ed ? Array.from(ed.getPkFieldNames())[0] : null)
            if (ed && pk) for (const row of ec.entity.find(entityName).condition(pk, 'in', ids).list()) {
                const field = NAME_FIELDS.find((name) => ed.isField(name) && row[name])
                found[row[pk]] = {title: field ? String(row[field]) : '', workEffortTypeEnumId: ed.isField('workEffortTypeEnumId') ? (row.workEffortTypeEnumId ?? null) : null}
            }
        }
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    } catch (err) {
        ec.logger.warn(`Records drive: the names of ${entityName} records not read, their ids shown: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
    for (const id of ids) {
        const row = found[id] || {}
        const link = ec.service.sync().name('ironstone.commons.PaletteServices.get#RecordLink').parameters({recordEntityName: entityName, id: id,
            workEffortTypeEnumId: row.workEffortTypeEnumId || null, partyTypeEnumId: row.partyTypeEnumId || null}).call()
        nameMap[entityName + '\n' + id] = {title: row.title || id, url: link?.url || null, icon: link?.icon || null}
    }
}

const clean = (text) => String(text == null ? '' : text).split('/').filter((part) => part && part !== '.').join('/')
driveId = null; rootLocation = null; folderPath = null; drivePathByLocation = {}
const locations = Array.from(locationList || []).map((location) => String(location || '')).filter((location) => location)
for (const drive of ec.entity.find('moqui.resource.ResourceDrive').condition('driveKindEnumId', 'RdkRecords').orderBy('driveId').useCache(true).list()) {
    const mapped = Array.from(ec.entity.find('moqui.resource.ResourceDriveRecordFolder').condition('driveId', drive.driveId)
            .condition('recordEntityName', recordEntityName).useCache(true).list())
    if (!mapped.length) continue
    const root = String(drive.rootLocation || '').replace(/\/+$/, '')
    driveId = drive.driveId
    rootLocation = root
    for (const location of locations) if (location.startsWith(root + '/')) drivePathByLocation[location] = clean(location.slice(root.length + 1))
    for (const row of mapped) {
        const pattern = clean(row.folderPath).split('/')
        if (!pattern.includes('*')) { folderPath = pattern.concat([String(recordId)]).join('/'); break }
        // a pattern: the folder of one of the record's files
        for (const path of Object.values(drivePathByLocation)) {
            const segments = path.split('/')
            if (segments.length <= pattern.length || segments[pattern.length] !== String(recordId)) continue
            if (pattern.every((part, index) => part === '*' || part === segments[index])) { folderPath = segments.slice(0, pattern.length + 1).join('/'); break }
        }
        if (folderPath) break
    }
    break
}

driveList = []
personalDriveId = null
recordsDriveId = null
tagList = []
pendingShareCount = 0
isAdmin = ec.user.isInGroup('ADMIN')
const drives = ec.service.sync().name('org.moqui.impl.FileServices.get#UserDrives').call()
if (ec.message.hasError()) return
personalDriveId = drives.personalDriveId
for (const drive of Array.from(drives.driveList || [])) {
    const isRecords = drive.driveKindEnumId === 'RdkRecords'
    if (isRecords && !recordsDriveId) recordsDriveId = drive.driveId
    driveList.push(Object.assign({}, drive, {isRecords: isRecords, isMirror: drive.driveKindEnumId === 'RdkMirror' || drive.repositoryKind === 'remote'}))
}
ec.message.pushErrors()
try {
    tagList = Array.from(ec.service.sync().name('org.moqui.impl.FileServices.get#Tags').requireNewTransaction(true).call().tagList || [])
    const shares = ec.service.sync().name('org.moqui.impl.FileServices.get#Shares').requireNewTransaction(true).call()
    pendingShareCount = Array.from(shares.incomingList || []).filter((share) => share.pending).length
} catch (err) {
    ec.logger.warn(`Files rail: tags or shares not read: ${err && err.message ? err.message : err}`)
} finally {
    if (ec.message.hasError()) ec.logger.warn(`Files rail: ${ec.message.getErrorsString()}`)
    ec.message.clearErrors()
    ec.message.popErrors()
}

const clean = (text) => String(text == null ? '' : text).split('/').filter((part) => part && part !== '.').join('/')
const L = (text) => ec.l10n.localize(text)
fileList = []; folder = null; drive = null; breadcrumbList = []; record = null; hiddenCount = 0
path = clean(path)
const out = ec.service.sync().name('org.moqui.impl.FileServices.list#Folder').parameters({driveId: driveId, path: path,
    recordLimit: limit || 200}).call()
if (ec.message.hasError()) return
folder = out.folder
drive = out.drive
hiddenCount = out.moreRecordCount || 0
breadcrumbList = Array.from(out.breadcrumbList || []).map((crumb) => Object.assign({}, crumb))
let rows = Array.from(out.fileList || []).map((row) => Object.assign({}, row))
const typeOf = (row) => ec.service.sync().name('ironstone.commons.DriveServices.get#FileType').parameters({name: row.name, isDirectory: row.isDirectory}).call()
if (drive.driveKindEnumId === 'RdkRecords') {
    const root = String(drive.rootLocation || '').replace(/\/+$/, '')
    // the record folders of a mapped folder (FileServices listed only those the user may see), named by their titles
    const recordRows = rows.filter((row) => row.recordEntityName && row.recordId)
    if (recordRows.length) {
        const names = ec.service.sync().name('ironstone.commons.DriveServices.get#RecordNames').parameter('recordList', recordRows).call()?.nameMap || {}
        for (const row of recordRows) {
            const named = names[row.recordEntityName + '\n' + row.recordId] || {}
            Object.assign(row, {recordTitle: named.title || row.recordId, recordUrl: named.url || null, recordIcon: named.icon || null})
        }
        recordRows.sort((left, right) => (right.modified || 0) - (left.modified || 0))
        rows = rows.filter((row) => !(row.recordEntityName && row.recordId)).concat(recordRows)
    }
    // inside a record's folder: the record, its content rows, its crumb by title
    const inner = Array.from(folder.recordList || [])[0] || null
    if (inner) {
        const info = ec.service.sync().name('ironstone.shared.ChatterServices.get#RecordInfo').parameters({recordEntityName: inner.recordEntityName,
            recordId: inner.recordId}).call()
        record = {recordEntityName: info.info?.recordEntityName || inner.recordEntityName, recordId: inner.recordId,
            title: info.title || inner.recordId, typeLabel: info.typeLabel || null, url: info.url || null, icon: info.icon || null,
            folderPath: inner.folderPath}
        for (const crumb of breadcrumbList) if (crumb.path === inner.folderPath) crumb.name = record.title
        // the content rows of the record by location: their description and type
        const contentByLocation = {}
        const content = info.info?.contentEntity
        if (content) {
            ec.message.pushErrors()
            try {
                const typeOut = ec.service.sync().name('ironstone.shared.RecordFilesServices.get#ContentType').parameters({info: info.info}).call()
                const enumTypeId = typeOut.contentType?.enumTypeId
                const labels = {}
                if (enumTypeId) for (const item of ec.entity.find('moqui.basic.Enumeration').condition('enumTypeId', enumTypeId).useCache(true).list())
                    labels[item.enumId] = item.description || item.enumId
                for (const row of ec.entity.find(content.entityName).condition(content.keyField, inner.recordId).list()) {
                    if (!row.contentLocation) continue
                    const typeId = row[content.typeField] ?? null
                    contentByLocation[String(row.contentLocation)] = {description: row.description ?? null, contentTypeEnumId: typeId,
                        contentTypeLabel: typeId ? (labels[typeId] || typeId) : null}
                }
            } catch (err) {
                ec.logger.warn(`Records drive: the content rows of ${inner.recordEntityName} ${inner.recordId} not read: ${err && err.message ? err.message : err}`)
            } finally { ec.message.clearErrors(); ec.message.popErrors() }
        }
        // the record's own folder: each content_ folder opened, its files shown in its place
        if (path === inner.folderPath) {
            const opened = []
            for (const row of rows) {
                if (!row.isDirectory || !/^content_/.test(row.name)) { opened.push(row); continue }
                ec.message.pushErrors()
                try {
                    const listed = ec.service.sync().name('org.moqui.impl.FileServices.list#Folder').parameters({driveId: driveId, path: row.path})
                            .requireNewTransaction(true).call()
                    if (!ec.message.hasError()) for (const child of Array.from(listed.fileList || [])) opened.push(Object.assign({}, child, {contentFolder: row.path}))
                    else opened.push(row)
                } finally { ec.message.clearErrors(); ec.message.popErrors() }
            }
            rows = opened
        }
        for (const row of rows) {
            const found = contentByLocation[`${root}/${row.path}`]
            if (found) Object.assign(row, found)
        }
    }
    // the mapped folders' crumbs by their labels (request is Requests)
    const mapped = Array.from(ec.entity.find('moqui.resource.ResourceDriveRecordFolder').condition('driveId', driveId).useCache(true).list())
    for (const crumb of breadcrumbList) {
        const found = crumb.path ? mapped.find((item) => clean(item.folderPath) === crumb.path && item.label) : null
        if (found) crumb.name = found.label
    }
}
// a folder reached through a share: the crumbs from the shared folder on
if (folder && folder.viaShareId) {
    ec.message.pushErrors()
    try {
        const shares = ec.service.sync().name('org.moqui.impl.FileServices.get#Shares').call()
        const share = Array.from(shares.incomingList || []).find((item) => item.shareId === folder.viaShareId)
        if (share) {
            const at = breadcrumbList.findIndex((crumb) => crumb.path === clean(share.path))
            breadcrumbList = [{name: L('Shared with me'), view: 'shared'}].concat(at >= 0 ? breadcrumbList.slice(at) : breadcrumbList.slice(-1))
        }
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
for (const row of rows) {
    const kind = typeOf(row)
    row.fileType = row.isRecordFolder ? 'folder' : (row.fileType || kind.fileType)
    row.icon = row.recordIcon || (row.isRecordFolder ? 'sym_o_folder_special' : kind.icon)
}
fileList = rows

const FILES = 'org.moqui.impl.FileServices'
const L = (text) => ec.l10n.localize(text)
fileList = []
drive = null
usedIndex = false
let rows = []
const names = {}
const nameOf = (id) => {
    if (!id) return null
    if (names[id] === undefined) {
        const account = ec.entity.find('moqui.security.UserAccount').condition('userId', id).useCache(true).disableAuthz().one()
        names[id] = account ? (account.userFullName || account.username || id) : id
    }
    return names[id]
}
const driveNames = {}
const driveName = (id) => {
    if (!id) return null
    if (driveNames[id] === undefined) {
        const access = ec.service.sync().name(`${FILES}.get#DriveAccess`).parameter('driveId', id).call()
        driveNames[id] = access.drive ? access.drive.driveName : null
    }
    return driveNames[id]
}
if (view === 'recent') {
    rows = Array.from(ec.service.sync().name(`${FILES}.find#Recent`).parameter('limit', limit || 100).call().resultList || [])
            .map((row) => Object.assign({}, row, {isDirectory: false, when: Math.max(row.lastOpened || 0, row.lastChanged || 0) || null}))
} else if (view === 'favorites') {
    rows = Array.from(ec.service.sync().name(`${FILES}.get#Favorites`).call().favoriteList || []).map((row) => Object.assign({}, row))
} else if (view === 'shared' || view === 'sharedByMe') {
    const shares = ec.service.sync().name(`${FILES}.get#Shares`).call()
    if (view === 'shared') {
        rows = Array.from(shares.incomingList || []).filter((share) => share.declinedDate == null).map((share) => Object.assign({}, share,
            {name: share.name || share.driveName, fromName: share.createdByName, modified: share.createdDate}))
    } else {
        const people = Array.from(shares.outgoingList || []).map((share) => Object.assign({}, share, {isLink: false,
            withText: share.sharedWithName || share.sharedWithUserGroupId || share.sharedWithEmail || share.sharedWithPartyId}))
        const links = Array.from(shares.linkList || []).map((share) => Object.assign({}, share, {isLink: true,
            withText: share.linkLabel || L('Link')}))
        rows = people.concat(links).map((share) => Object.assign(share, {name: share.name || driveName(share.driveId),
            driveName: driveName(share.driveId), modified: share.createdDate}))
        rows.sort((left, right) => (right.createdDate || 0) - (left.createdDate || 0))
    }
} else if (view === 'tag') {
    // only a tag the user sees (their own or everyone's); its files across the drives the user may open
    const tag = Array.from(ec.service.sync().name(`${FILES}.get#Tags`).call().tagList || []).find((item) => item.tagId === tagId)
    if (!tag) { ec.message.addError(L('Tag not found')); return }
    const found = ec.service.sync().name(`${FILES}.find#Resources`).parameters({tagId: tagId, limit: limit || 100}).call()
    if (ec.message.hasError()) return
    usedIndex = found.usedIndex === true
    rows = Array.from(found.resultList || []).map((row) => Object.assign({}, row))
} else if (view === 'search') {
    const parameters = {limit: limit || 100, text: text || null, fileType: fileType || null, modifiedPeriod: modifiedPeriod || null,
        modifiedByUserId: modifiedByUserId || null}
    if (driveId) { parameters.driveId = driveId; parameters.path = path || null }
    const found = ec.service.sync().name(`${FILES}.find#Resources`).parameters(parameters).call()
    if (ec.message.hasError()) return
    usedIndex = found.usedIndex === true
    rows = Array.from(found.resultList || []).map((row) => Object.assign({}, row))
} else if (view === 'trash') {
    if (!driveId) { ec.message.addError(L('Choose a drive')); return }
    const access = ec.service.sync().name(`${FILES}.get#DriveAccess`).parameter('driveId', driveId).call()
    if (!access.drive || access.level < 1 || access.drive.driveKindEnumId === 'RdkRecords') { ec.message.addError(L('Drive not found')); return }
    drive = Object.assign({}, access.drive, {canWrite: access.canWrite})
    rows = Array.from(ec.service.sync().name(`${FILES}.list#Trash`).parameter('driveId', driveId).call().trashList || [])
            .map((row) => Object.assign({}, row, {driveId: driveId, driveName: access.drive.driveName, modified: row.trashedDate,
                trashedByName: nameOf(row.trashedByUserId)}))
} else { ec.message.addError(`Unknown view ${view}`); return }
if (ec.message.hasError()) return
for (const row of rows) {
    const kind = ec.service.sync().name('ironstone.commons.DriveServices.get#FileType').parameters({name: row.name, isDirectory: row.isDirectory === true}).call()
    row.fileType = row.fileType || kind.fileType
    row.icon = kind.icon
    if (!row.driveName) row.driveName = driveName(row.driveId)
    if (row.modifiedByUserId && !row.modifiedByName) row.modifiedByName = nameOf(row.modifiedByUserId)
    const slash = String(row.path || '').lastIndexOf('/')
    row.folderPath = slash > 0 ? String(row.path).slice(0, slash) : ''
}
fileList = rows

const FILES = 'org.moqui.impl.FileServices'
const clean = (text) => String(text == null ? '' : text).split('/').filter((part) => part && part !== '.').join('/')
item = null; drive = null; access = null; shareList = []; linkList = []; record = null
path = clean(path)
const info = ec.service.sync().name(`${FILES}.get#ResourceInfo`).parameters({driveId: driveId, path: path}).call()
if (ec.message.hasError()) return
item = Object.assign({}, info.resource)
delete item.location
delete item.recordList
const levels = ec.service.sync().name(`${FILES}.get#DriveAccess`).parameters({driveId: driveId, path: path}).call()
drive = levels.drive
const isRecords = drive?.driveKindEnumId === 'RdkRecords'
access = {level: levels.level, permissionEnumId: levels.permissionEnumId, isOwner: levels.isOwner, canWrite: levels.canWrite,
    canUpload: levels.canUpload, canShare: levels.level >= 2 && !isRecords, viaShareId: levels.viaShareId ?? null}
const kind = ec.service.sync().name('ironstone.commons.DriveServices.get#FileType').parameters({name: item.name, isDirectory: item.isDirectory}).call()
item.fileType = kind.fileType
item.icon = kind.icon
if (item.modifiedByUserId) {
    const account = ec.entity.find('moqui.security.UserAccount').condition('userId', item.modifiedByUserId).useCache(true).disableAuthz().one()
    item.modifiedByName = account ? (account.userFullName || account.username) : item.modifiedByUserId
}
// the favorite, tags and shared mark, from the folder's list (a file shared alone has no folder to read)
const slash = path.lastIndexOf('/')
ec.message.pushErrors()
try {
    const parent = ec.service.sync().name(`${FILES}.list#Folder`).parameters({driveId: driveId, path: slash > 0 ? path.slice(0, slash) : ''})
            .requireNewTransaction(true).call()
    const row = ec.message.hasError() ? null : Array.from(parent.fileList || []).find((entry) => entry.path === path)
    if (row) Object.assign(item, {favorite: row.favorite, tags: row.tags || [], shared: row.shared})
} finally { ec.message.clearErrors(); ec.message.popErrors() }
if (item.tags == null) item.tags = []
const shares = ec.service.sync().name(`${FILES}.get#Shares`).parameters({driveId: driveId, path: path}).call()
shareList = Array.from(shares.outgoingList || [])
linkList = Array.from(shares.linkList || [])
// a records drive path: its innermost record, with its title and link
const inner = Array.from(info.resource.recordList || [])[0] || null
if (inner) {
    const named = ec.service.sync().name('ironstone.commons.DriveServices.get#RecordNames').parameter('recordList', [inner]).call()?.nameMap || {}
    const found = named[inner.recordEntityName + '\n' + inner.recordId] || {}
    record = Object.assign({}, inner, {title: found.title || inner.recordId, url: found.url || null, icon: found.icon || null})
}

const clean = (text) => String(text == null ? '' : text).split('/').filter((part) => part && part !== '.').join('/')
conflictList = []
path = clean(path)
// each folder through list#Folder, as the user: a folder the user may not read has no names to answer
const listed = {}
const entries = (folder) => {
    if (listed[folder] === undefined) {
        listed[folder] = {}
        ec.message.pushErrors()
        try {
            const out = ec.service.sync().name('org.moqui.impl.FileServices.list#Folder').parameters({driveId: driveId, path: folder})
                    .requireNewTransaction(true).call()
            if (!ec.message.hasError()) for (const row of Array.from(out.fileList || [])) listed[folder][row.name] = row
        } finally { ec.message.clearErrors(); ec.message.popErrors() }
    }
    return listed[folder]
}
for (const raw of Array.from(nameList || [])) {
    const relative = clean(raw)
    if (!relative || String(raw).split('/').includes('..')) continue
    const full = path ? `${path}/${relative}` : relative
    const slash = full.lastIndexOf('/')
    const found = entries(slash > 0 ? full.slice(0, slash) : '')[full.slice(slash + 1)]
    if (found) conflictList.push({name: relative, path: full, isDirectory: found.isDirectory === true})
}

const L = (text) => ec.l10n.localize(text)
uploadedList = []
const files = (Array.isArray(contentFile) ? contentFile : [contentFile]).filter((file) => file != null && typeof file === 'object')
if (!files.length) { ec.message.addError(L('Choose one or more files to upload')); return }
const relatives = relativePath == null ? [] : (Array.isArray(relativePath) ? relativePath : [relativePath]).map((item) => String(item || ''))
const parameters = {driveId: driveId, path: path || null, fileList: files, conflictPolicy: conflictPolicy || 'replace', versionNote: versionNote || null}
if (relatives.length === files.length && relatives.some((item) => item.includes('/'))) parameters.relativePathList = relatives
const out = ec.service.sync().name('org.moqui.impl.FileServices.upload#Resource').parameters(parameters).call()
if (ec.message.hasError()) return
uploadedList = Array.from(out.uploadedList || [])
const count = (outcome) => uploadedList.filter((row) => row.outcome === outcome).length
const parts = []
if (count('created')) parts.push(ec.resource.expand('${count} added', '', {count: count('created')}))
if (count('replaced')) parts.push(ec.resource.expand('${count} replaced', '', {count: count('replaced')}))
if (count('renamed')) parts.push(ec.resource.expand('${count} kept with a new name', '', {count: count('renamed')}))
if (count('skipped')) parts.push(ec.resource.expand('${count} skipped', '', {count: count('skipped')}))
if (count('failed')) parts.push(ec.resource.expand('${count} failed', '', {count: count('failed')}))
message = (uploadedList.length === 1 && uploadedList[0].outcome !== 'failed' ? ec.resource.expand('Uploaded ${name}', '', {name: uploadedList[0].name})
        : L('Upload') + ': ' + parts.join(', '))
for (const row of uploadedList) if (row.outcome === 'failed') ec.logger.warn(`Upload to drive ${driveId}: ${row.name} failed: ${row.error}`)

const clean = (value) => String(value == null ? '' : value).split('/').filter((part) => part && part !== '.').join('/')
const L = (value) => ec.l10n.localize(value)
newPath = null
versionName = null
path = clean(path)
let target = path
if (!replace) {
    const fileName = String(name || '').trim()
    if (!fileName || fileName.includes('/') || fileName === '.' || fileName === '..' || fileName.startsWith('.trash')) { ec.message.addError(L('That is not a file name')); return }
    target = path ? `${path}/${fileName}` : fileName
}
if (!replace) {
    ec.message.pushErrors()
    let exists = false
    try {
        ec.service.sync().name('org.moqui.impl.FileServices.get#ResourceInfo').parameters({driveId: driveId, path: target}).requireNewTransaction(true).call()
        exists = !ec.message.hasError()
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
    if (exists) { ec.message.addError(L('Something by that name is already there')); return }
}
const out = ec.service.sync().name('org.moqui.impl.FileServices.save#Text').parameters({driveId: driveId, path: target, text: text ?? '',
    versionNote: versionNote || null}).call()
if (ec.message.hasError()) return
newPath = target
versionName = out.versionName ?? null

text = null
const info = ec.service.sync().name('org.moqui.impl.FileServices.get#ResourceInfo').parameters({driveId: driveId, path: path, opened: true}).call()
if (ec.message.hasError()) return
const resource = info.resource
if (resource.isDirectory || !resource.isText) { ec.message.addError(ec.l10n.localize('Only a text file opens in the editor')); return }
if (resource.size != null && Number(resource.size) > 2 * 1024 * 1024) { ec.message.addError(ec.l10n.localize('This file is too large to edit here; download it')); return }
text = ec.resource.getLocationReference(resource.location).getText() ?? ''
versionName = resource.versionName ?? null
canWrite = resource.canWrite === true

const clean = (text) => String(text == null ? '' : text).split('/').filter((part) => part && part !== '.').join('/')
const L = (text) => ec.l10n.localize(text)
notifiedUserIds = []
path = clean(path)
const link = isLink === 'Y' || isLink === true || isLink === 'true'
const parameters = {driveId: driveId, path: path, permissionEnumId: permissionEnumId || 'RspView', expireDate: expireDate ?? null,
    note: note || null, isLink: link ? 'Y' : 'N'}
let userId = null, groupId = null
if (link) Object.assign(parameters, {password: password || null, linkLabel: linkLabel || null})
else {
    const text = String(shareWith || '')
    if (text.startsWith('user:')) userId = text.slice(5)
    else if (text.startsWith('group:')) groupId = text.slice(6)
    else if (text) userId = text
    if (!userId && !groupId) { ec.message.addError(L('Choose a person or a group to share with')); return }
    if (userId && userId === ec.user.userId) { ec.message.addError(L('You have this already')); return }
    if (userId) parameters.sharedWithUserId = userId
    else parameters.sharedWithUserGroupId = groupId
}
const out = ec.service.sync().name('org.moqui.impl.FileServices.share#Resource').parameters(parameters).call()
if (ec.message.hasError()) return
shareId = out.shareId
linkToken = out.linkToken ?? null
linkPath = out.linkPath ?? null
const access = ec.service.sync().name('org.moqui.impl.FileServices.get#DriveAccess').parameter('driveId', driveId).call()
const itemName = path ? path.slice(path.lastIndexOf('/') + 1) : (access.drive ? access.drive.driveName : driveId)
if (link) { message = L('Link made: copy it now, it is shown only once'); return }
// the person or the group is told, with the item in Files
const info = ec.service.sync().name('org.moqui.impl.FileServices.get#ResourceInfo').parameters({driveId: driveId, path: path}).call()
const isDirectory = !path || !!(info.resource && info.resource.isDirectory)
const query = isDirectory ? `drive=${encodeURIComponent(driveId)}&path=${encodeURIComponent(path)}`
        : `view=shared&drive=${encodeURIComponent(driveId)}&file=${encodeURIComponent(path)}`
const url = `/qapps/Commons/Files?${query}`
const authorName = ec.user.userAccount?.userFullName || ec.user.username
ec.message.pushErrors()
try {
    const nm = ec.makeNotificationMessage().topic('FileShare').message({fileName: itemName, location: url, authorUserId: ec.user.userId,
        authorName: authorName, driveId: driveId, path: path, isDirectory: isDirectory, permissionEnumId: parameters.permissionEnumId,
        note: note || null}).link(url)
    if (userId) nm.userId(userId)
    else nm.userGroupId(groupId)
    if (nm.actorUserId) nm.actorUserId(ec.user.userId)
    if (nm.appName) nm.appName('Commons')
    nm.send()
    notifiedUserIds = Array.from(nm.getNotifyUserIds() ?? []).filter((id) => id !== ec.user.userId)
} catch (err) {
    ec.logger.error(`File share notification for ${itemName} in drive ${driveId} not sent: ${err && err.message ? err.message : err}`)
} finally {
    if (ec.message.hasError()) ec.logger.error(`File share notification for ${itemName}: ${ec.message.getErrorsString()}`)
    ec.message.clearErrors()
    ec.message.popErrors()
}
message = ec.resource.expand('Shared ${name}', '', {name: itemName})

const text = String(term || '').trim()
optionList = []
const users = ec.service.sync().name('ironstone.shared.ChatterServices.search#Users').parameters({term: text, limit: 10}).call().userList || []
for (const user of Array.from(users)) if (user.value !== ec.user.userId) optionList.push({value: 'user:' + user.value, label: user.label, kind: 'user'})
if (text.length >= 2) {
    const lower = text.toLowerCase()
    for (const group of ec.entity.find('moqui.security.UserGroup').useCache(true).disableAuthz().list()) {
        if (optionList.length >= 16) break
        const name = String(group.description || group.userGroupId)
        if (name.toLowerCase().includes(lower) || String(group.userGroupId).toLowerCase().includes(lower))
            optionList.push({value: 'group:' + group.userGroupId, label: name + ' (' + ec.l10n.localize('group') + ')', kind: 'group'})
    }
}

fileList = []
const out = ec.service.sync().name('ironstone.commons.DriveServices.find#FileRows').parameters({view: 'recent', limit: (limit || 5) * 3}).call()
if (ec.message.hasError()) return
const nowMillis = Number(String(ec.user.nowTimestamp))
const fmt = (millis, pattern) => ec.l10n.format(new Date(Number(millis)), pattern)
for (const row of Array.from(out.fileList || []).slice(0, limit || 5)) {
    const when = row.when || row.modified
    const sameDay = when && fmt(when, 'yyyy-MM-dd') === fmt(nowMillis, 'yyyy-MM-dd')
    fileList.push({name: row.name, driveName: row.driveName, folderPath: row.folderPath, icon: row.icon, fileType: row.fileType,
        whenText: when ? (sameDay ? fmt(when, 'h:mm a') : fmt(when, 'MMM d')) : '', byName: row.modifiedByName || null,
        url: `/qapps/Commons/Files?drive=${encodeURIComponent(row.driveId)}&path=${encodeURIComponent(row.folderPath)}&file=${encodeURIComponent(row.path)}`})
}

rows = []
const out = ec.service.sync().name('ironstone.commons.DriveServices.find#FileRows').parameters({view: 'search', text: text, limit: (limit || 5) * 3}).call()
if (ec.message.hasError()) return
for (const row of Array.from(out.fileList || []).slice(0, limit || 5)) {
    const folderQuery = `drive=${encodeURIComponent(row.driveId)}&path=${encodeURIComponent(row.isDirectory ? row.path : row.folderPath)}`
    rows.push({title: row.name, subtitle: [row.driveName, row.folderPath].filter((part) => part).join(' · '), icon: row.icon,
        url: `/qapps/Commons/Files?${folderQuery}${row.isDirectory ? '' : '&file=' + encodeURIComponent(row.path)}`})
}
moreUrl = `/qapps/Commons/Files?q=${encodeURIComponent(text)}`

isAdmin = ec.user.isInGroup('ADMIN')
driveList = []
const out = ec.service.sync().name('org.moqui.impl.FileServices.get#UserDrives').parameters({includeArchived: true, includeUsage: true}).call()
if (ec.message.hasError()) return
const STORAGE = {folder: 'Folder', 'git-db': 'Version-controlled in the database', 'git-local': 'Version-controlled on disk',
    'git-remote': 'Mirror', other: 'Records'}
const fmtSize = (bytes) => {
    if (bytes == null) return ''
    const n = Number(bytes)
    if (n >= 1073741824) return (n / 1073741824).toFixed(1) + ' GB'
    if (n >= 1048576) return (n / 1048576).toFixed(1) + ' MB'
    if (n >= 1024) return Math.round(n / 1024) + ' KB'
    return n + ' B'
}
const LEVEL = {RdpView: 'View', RdpEdit: 'Edit', RdpManage: 'Manage'}
for (const drive of Array.from(out.driveList || [])) {
    const isRecords = drive.driveKindEnumId === 'RdkRecords'
    const quota = drive.quotaBytes != null ? Number(drive.quotaBytes) : null
    const used = drive.usedBytes != null ? Number(drive.usedBytes) : null
    driveList.push(Object.assign({}, drive, {isRecords: isRecords, isMirror: drive.repositoryKind === 'remote' || drive.driveKindEnumId === 'RdkMirror',
        storageLabel: ec.l10n.localize(isRecords ? 'Records' : (STORAGE[drive.storage] || drive.storage)),
        usedText: used != null ? (fmtSize(used) + (quota ? ' ' + ec.l10n.localize('of') + ' ' + fmtSize(quota) : '')) : '',
        usedPercent: quota && used != null ? Math.min(100, Math.round(used * 100 / quota)) : null,
        levelLabel: ec.l10n.localize(drive.isOwner ? 'Owner' : (LEVEL[drive.permissionEnumId] || 'View')),
        canManage: drive.level >= 3 && !isRecords && drive.driveKindEnumId !== 'RdkPersonal'}))
}

const ids = (Array.isArray(memberUserIds) ? memberUserIds : String(memberUserIds || '').split(',')).map((id) => String(id || '').trim())
        .filter((id) => id && id !== ec.user.userId).map((id) => id.startsWith('user:') ? id.slice(5) : id)
const memberList = Array.from(new Set(ids)).map((id) => ({userId: id, permissionEnumId: memberPermissionEnumId || 'RdpEdit'}))
const parameters = {driveName: driveName, description: description || null, storage: storage || 'folder', memberList: memberList,
    quotaBytes: quotaMb != null && Number(quotaMb) > 0 ? Math.round(Number(quotaMb) * 1048576) : null}
if (storage === 'mirror') Object.assign(parameters, {remoteUrl: remoteUrl || null, branch: branch || null, username: username || null,
    accessToken: accessToken || null, fetchIntervalMinutes: fetchIntervalMinutes ?? null})
const out = ec.service.sync().name('org.moqui.impl.FileServices.create#Drive').parameters(parameters).call()
if (ec.message.hasError()) return
driveId = out.driveId
message = ec.resource.expand('Drive ${name} made', '', {name: driveName})

const L = (text) => ec.l10n.localize(text)
const shares = ec.service.sync().name('org.moqui.impl.FileServices.get#Shares').call()
if (ec.message.hasError()) return
const driveNames = {}
const driveName = (id) => {
    if (driveNames[id] === undefined) {
        const access = ec.service.sync().name('org.moqui.impl.FileServices.get#DriveAccess').parameter('driveId', id).call()
        driveNames[id] = access.drive ? access.drive.driveName : id
    }
    return driveNames[id]
}
const PERMISSION = {RspView: 'View', RspEdit: 'Edit', RspUpload: 'Upload only'}
const fmt = (millis) => millis ? ec.l10n.format(new Date(Number(millis)), 'yyyy-MM-dd') : ''
const decorate = (share) => {
    const path = share.path || ''
    const slash = path.lastIndexOf('/')
    const folder = slash > 0 ? path.slice(0, slash) : ''
    const query = share.isDirectory ? `drive=${encodeURIComponent(share.driveId)}&path=${encodeURIComponent(path)}`
            : `drive=${encodeURIComponent(share.driveId)}&path=${encodeURIComponent(folder)}&file=${encodeURIComponent(path)}`
    return Object.assign({}, share, {driveName: share.driveName || driveName(share.driveId), name: share.name || driveName(share.driveId),
        permissionLabel: L(PERMISSION[share.permissionEnumId] || 'View'), createdText: fmt(share.createdDate), expireText: fmt(share.expireDate),
        lastOpenedText: fmt(share.lastOpenedDate), url: `/qapps/Commons/Files?${query}`, icon: share.isDirectory ? 'sym_o_folder' : 'sym_o_draft'})
}
incomingList = Array.from(shares.incomingList || []).map((share) => {
    const row = decorate(share)
    if (!share.isDirectory) row.url = `/qapps/Commons/Files?view=shared&drive=${encodeURIComponent(share.driveId)}&file=${encodeURIComponent(share.path || '')}`
    row.stateLabel = share.pending ? L('Waiting for you') : (share.declinedDate ? L('Declined') : L('Accepted'))
    return row
}).sort((left, right) => (left.pending === right.pending ? (right.createdDate || 0) - (left.createdDate || 0) : (left.pending ? -1 : 1)))
outgoingList = Array.from(shares.outgoingList || []).map((share) => Object.assign(decorate(share), {withText: share.sharedWithName
        || share.sharedWithUserGroupId || share.sharedWithEmail || share.sharedWithPartyId || '',
    stateLabel: share.declinedDate ? L('Declined') : (share.acceptedDate ? L('Accepted') : L('Not answered yet'))}))
linkList = Array.from(shares.linkList || []).map((share) => decorate(share))
